From 84ae0a9e113b75ad8ad015b7a892c744478ea10c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:36:32 +0100
Subject: [PATCH] dpms: turn off the keyboard backlight whenever all displays
 turn off

The keyboard backlight was only turned off when PowerDevil itself turned
the displays off on idle, so pressing Esc on the lock screen left it lit.
Follow the displays' power state instead and restore it when one turns on.

BUG: 466345
---
 daemon/actions/bundled/dpms.cpp | 34 +++++++++++++++++++++++++++++++++
 daemon/actions/bundled/dpms.h   |  5 +++++
 2 files changed, 39 insertions(+)

diff --git a/daemon/actions/bundled/dpms.cpp b/daemon/actions/bundled/dpms.cpp
index 2b8ec6e60..bc8000ef6 100644
--- a/daemon/actions/bundled/dpms.cpp
+++ b/daemon/actions/bundled/dpms.cpp
@@ -17,8 +17,11 @@
 #include <QDBusMessage>
 #include <QDBusPendingCall>
 #include <QGuiApplication>
+#include <QScreen>
 #include <QTimer>

+#include <algorithm>
+
 #include <KActionCollection>
 #include <KGlobalAccel>
 #include <KLocalizedString>
@@ -56,6 +59,16 @@ DPMS::DPMS(QObject *parent)
     connect(core()->suspendController(), &SuspendController::aboutToSuspend, this, &DPMS::onAboutToSuspend);
     connect(core()->suspendController(), &SuspendController::resumeFromSuspend, this, &DPMS::onResumeFromSuspend);

+    // The display can also be turned off without us, e.g. by pressing Esc on the lock screen
+    connect(m_dpms.get(), &KScreen::Dpms::modeChanged, this, [this](KScreen::Dpms::Mode mode, QScreen *screen) {
+        if (mode == KScreen::Dpms::On) {
+            m_screensOff.remove(screen);
+        } else {
+            m_screensOff.insert(screen);
+        }
+        onScreensOffChanged();
+    });
+
     KActionCollection *actionCollection = new KActionCollection(this);
     actionCollection->setComponentDisplayName(i18nc("Name for powerdevil shortcuts category", "Power Management"));

@@ -119,6 +132,27 @@ void DPMS::onIdleTimeout(std::chrono::milliseconds /*timeout*/)
     }
 }

+void DPMS::onScreensOffChanged()
+{
+    const auto screens = QGuiApplication::screens();
+    const bool allOff = !screens.isEmpty() && std::ranges::all_of(screens, [this](QScreen *screen) {
+        return m_screensOff.contains(screen);
+    });
+
+    KeyboardBrightnessController *controller = core()->keyboardBrightnessController();
+    if (allOff) {
+        const int keyboardBrightness = controller->brightness();
+        if (m_oldKeyboardBrightness == 0 && keyboardBrightness > 0) {
+            qCDebug(POWERDEVIL) << "DPMS: all displays turned off, turning off keyboard backlight";
+            m_oldKeyboardBrightness = keyboardBrightness;
+            controller->setBrightness(0);
+        }
+    } else if (m_oldKeyboardBrightness > 0) {
+        controller->setBrightness(m_oldKeyboardBrightness);
+        m_oldKeyboardBrightness = 0;
+    }
+}
+
 void DPMS::setKeyboardBrightnessHelper(int brightness)
 {
     trigger({{u"KeyboardBrightness"_s, QVariant::fromValue(brightness)}});
diff --git a/daemon/actions/bundled/dpms.h b/daemon/actions/bundled/dpms.h
index 47dc2fd52..f084b68b1 100644
--- a/daemon/actions/bundled/dpms.h
+++ b/daemon/actions/bundled/dpms.h
@@ -10,6 +10,9 @@
 #include <powerdevilaction.h>

 #include <QScopedPointer>
+#include <QSet>
+
+class QScreen;

 namespace KScreen
 {
@@ -47,6 +50,7 @@ private Q_SLOTS:
 private:
     void setKeyboardBrightnessHelper(int brightness);
     void registerStandardIdleTimeout();
+    void onScreensOffChanged();

     std::chrono::milliseconds m_idleTimeoutWhenUnlocked{-1};
     std::chrono::milliseconds m_idleTimeoutWhenLocked{-1};
@@ -57,6 +61,7 @@ private:

     int m_oldKeyboardBrightness = 0;
     QScopedPointer<KScreen::Dpms> m_dpms;
+    QSet<QScreen *> m_screensOff;

     bool m_lockBeforeTurnOff = false;
     void lockScreen();
